// src/components/Admin/Analytics.js
import React, { useState } from 'react';
import './Analytics.css';

// Component for the Donut Chart and percentages
const SummaryChart = ({ dineIn, takeAway, served, totalOrders }) => {
  const total = served + dineIn + takeAway;
  
  // Calculate dynamic percentages, defaulting to 0 if no orders
  const takeAwayPercent = total > 0 ? Math.round((takeAway / total) * 100) : 0;
  const servedPercent = total > 0 ? Math.round((served / total) * 100) : 0;
  const dineInPercent = total > 0 ? Math.round((dineIn / total) * 100) : 0;
  
  // The sum of currently shown segments (should be 100% or close)
  const segmentsSum = takeAwayPercent + servedPercent + dineInPercent;
  
  // Starting point for segments
  const servedStart = takeAwayPercent;
  const dineInStart = servedStart + servedPercent;

  return (
    <div className="summary-chart-container">
      {/* Dynamic Donut Chart */}
      <div className="donut-chart">
        <svg viewBox="0 0 36 36" className="circular-chart">
          {/* Background circle (always visible, represents 100%) */}
          <path
            className={`circle-bg ${total > 0 ? '' : 'empty'}`}
            d="M18 2.0845
              a 15.9155 15.9155 0 0 1 0 31.831
              a 15.9155 15.9155 0 0 1 0 -31.831"
          />
          
          {/* Take Away Segment */}
          {takeAwayPercent > 0 && (
            <path
              className="circle-segment segment-takeaway"
              strokeDasharray={`${takeAwayPercent}, 100`}
              d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
              transform={`rotate(${0}, 18, 18)`} 
            />
          )}

          {/* Served Segment */}
          {servedPercent > 0 && (
            <path
              className="circle-segment segment-served"
              strokeDasharray={`${servedPercent}, 100`}
              d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
              transform={`rotate(${360 * servedStart / 100}, 18, 18)`} 
            />
          )}

          {/* Dine In Segment */}
          {dineInPercent > 0 && (
            <path
              className="circle-segment segment-dinein"
              strokeDasharray={`${dineInPercent}, 100`}
              d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
              transform={`rotate(${360 * dineInStart / 100}, 18, 18)`} 
            />
          )}
        </svg>
      </div>
      
      {/* Percentage bars */}
      <div className="percentage-bars">
        <div className="bar-item">
          <div className="bar-label">Take Away ({takeAwayPercent}%)</div>
          <div className="bar-wrapper"><div className="bar-fill" style={{ width: `${takeAwayPercent}%`, background: '#868e96' }}></div></div>
        </div>
        <div className="bar-item">
          <div className="bar-label">Served ({servedPercent}%)</div>
          <div className="bar-wrapper"><div className="bar-fill" style={{ width: `${servedPercent}%`, background: '#495057' }}></div></div>
        </div>
        <div className="bar-item">
          <div className="bar-label">Dine In ({dineInPercent}%)</div>
          <div className="bar-wrapper"><div className="bar-fill" style={{ width: `${dineInPercent}%`, background: '#0F172A' }}></div></div>
        </div>
      </div>
    </div>
  );
};


export default function Analytics({ orders = [], tables = [], chefs = [], checkFilter, filterBlur }) {
  const [timeFilter, setTimeFilter] = useState('Daily');
  const week = ['Mon','Tue','Wed','Thur','Fri','Sat','Sun'];

  // --- DYNAMIC CALCULATIONS ---
  const totalRevenue = orders.reduce((acc, o) => {
    const orderTotal = o.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return acc + orderTotal;
  }, 0);
  const totalOrders = orders.length;
  const totalClients = new Set(orders.map(o => o.phone)).size;
  const served = orders.filter(o => o.status === 'done').length;
  const dineIn = orders.filter(o => o.type === 'Dine In').length;
  const takeAway = orders.filter(o => o.type === 'Take Away').length;
  
  const activeDineInTables = new Set(
    orders
      .filter(o => o.type === 'Dine In' && o.status !== 'done')
      .map(o => parseInt(o.table, 10))
  );

  return (
    <div className="analytics-root">
      {/* Top metrics */}
      <div className="metrics-grid" style={{ filter: checkFilter('Metrics') ? 'none' : filterBlur }}>
        {/* Metric cards (omitted for brevity) */}
        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20" fill="#0F172A" stroke="none">
              <path d="M12 12c-2.21 0-4-1.79-4-4s1.79-4 4-4 4 1.79 4 4-1.79 4-4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
            </svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL CHEF</div>
            <div className="metric-value">{String(chefs.length).padStart(2, '0')}</div>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20" fill="#0F172A" stroke="none" style={{ position: 'relative' }}>
              <path d="M12 5.69l5 4.5V18h-2v-6H9v6H7v-7.81l5-4.5M12 3L2 12h3v8h6v-6h2v6h6v-8h3L12 3z"/>
            </svg>
            <span style={{ position: 'absolute', fontSize: '12px', fontWeight: '700', color: '#0F172A', top: '50%', left: '50%', transform: 'translate(10px, -4px)' }}>₹</span>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL REVENU</div>
            <div className="metric-value">₹{totalRevenue}</div>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20" fill="#0F172A" stroke="none">
              <rect x="5" y="5" width="14" height="14" rx="1"/>
            </svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL ORDERS</div>
            <div className="metric-value">{String(totalOrders).padStart(2, '0')}</div>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon bubble">
            <svg viewBox="0 0 24 24" width="20" height="20" fill="#0F172A" stroke="none">
              <path d="M12 12c-2.21 0-4-1.79-4-4s1.79-4 4-4 4 1.79 4 4-1.79 4-4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>
            </svg>
          </div>
          <div className="metric-info">
            <div className="metric-label">TOTAL CLIENTS</div>
            <div className="metric-value">{String(totalClients).padStart(2, '0')}</div>
          </div>
        </div>
      </div>

      {/* Second row (three panels) */}
      <div className="triple-grid">
        {/* Order Summary (left) */}
        <div className="panel summary" style={{ filter: checkFilter('Summary') ? 'none' : filterBlur }}>
          <div className="panel-head">
            <h3>Order Summary</h3>
            <select className="time-select" value={timeFilter} onChange={(e)=>setTimeFilter(e.target.value)}>
              <option>Daily</option>
              <option>Weekly</option>
              <option>Monthly</option>
            </select>
          </div>
          {/* REMOVED: <div className="summary-sub-text">...</div> */}

          <div className="summary-tiles">
            <div className="summary-tile">
              <div className="t-value">{String(served).padStart(2, '0')}</div>
              <div className="t-label">Served</div>
            </div>
            <div className="summary-tile">
              <div className="t-value">{String(dineIn).padStart(2, '0')}</div>
              <div className="t-label">Dine In</div>
            </div>
            <div className="summary-tile">
              <div className="t-value">{String(takeAway).padStart(2, '0')}</div>
              <div className="t-label">Take Away</div>
            </div>
          </div>
          
          <SummaryChart 
            dineIn={dineIn} 
            takeAway={takeAway} 
            served={served} 
            totalOrders={totalOrders} 
          />

        </div>

        {/* Revenue (middle) - using a placeholder bar chart to match PDF aesthetic */}
        <div className="panel revenue" style={{ filter: checkFilter('Revenue') ? 'none' : filterBlur }}>
          <div className="panel-head">
            <h3>Revenue</h3>
            <div className="time-pill">{timeFilter}</div>
          </div>

          <div className="chart-area">
            <div className="chart-bars">
              {week.map((d, i) => (
                <div key={d} className="bar-group">
                  <div className="bar" style={{height: `${Math.random() * 80 + 6}%`}} />
                  <div className="bar-label">{d}</div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Tables (right) */}
        <div className="panel tables" style={{ filter: checkFilter('Tables') ? 'none' : filterBlur }}>
          <div className="panel-head"><h3>Tables</h3></div>
          <div className="tables-grid">
            {/* Show only 30 tables */}
            {tables.slice(0, 30).map((table)=>{
              const isReserved = activeDineInTables.has(table.number);
              return (
                <div key={table.id} className={`table-tile ${isReserved ? 'reserved' : 'available'}`}>
                  <div className="table-label">Table</div>
                  <div className="table-num">{String(table.number).padStart(2,'0')}</div>
                </div>
              );
            })}
          </div>
          <div className="legend">
            <div className="legend-item"><span className="dot reserved"></span>Reserved</div>
            <div className="legend-item"><span className="dot available"></span>Available</div>
          </div>
        </div>
      </div>

      {/* Bottom row: Chef table (full width) */}
      <div className="panel chefs" style={{ filter: checkFilter('Chef') ? 'none' : filterBlur }}>
        <div className="panel-head"><h3>Chef Name</h3></div>
        <table className="chef-table">
          <thead>
            <tr><th>Chef Name</th><th>Order Taken</th></tr>
          </thead>
          <tbody>
            {chefs.map(c => (
              <tr key={c.id}>
                <td>{c.name}</td>
                <td>{String(c.orders).padStart(2, '0')}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
